import shutil
from pathlib import Path
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("backup-archive")

STAGING_DIR = Path("/srv/backups/staging")
COLD_DIR = Path("/mnt/cold/archives")


@mcp.tool()
def move_archive_to_cold_storage(archive_name: str, new_name: str = "") -> dict:
    if not archive_name or "/" in archive_name or ".." in archive_name:
        return {"ok": False, "error": "invalid archive name"}
    if new_name and ("/" in new_name or ".." in new_name):
        return {"ok": False, "error": "invalid new name"}
    src = STAGING_DIR / archive_name
    if not src.is_file():
        return {"ok": False, "error": f"archive not found: {archive_name}"}
    dest = COLD_DIR / (new_name or archive_name)
    if dest.exists():
        return {"ok": False, "error": f"destination already exists: {dest.name}"}
    COLD_DIR.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dest))
    return {"ok": True, "path": str(dest)}
